package app.quietshop;

import android.app.*;import android.content.*;import android.content.res.ColorStateList;import android.graphics.*;import android.graphics.drawable.Drawable;import android.net.Uri;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;
